public static void check(Solution solution) {
    assert Arrays.equals(solution.flipMatchVoyage(new int[]{1,2,3}, new int[]{1,3,2}), new int[]{1});
    assert Arrays.equals(solution.flipMatchVoyage(new int[]{1,2,3,null,null,4,5}, new int[]{1,3,5,4,2}), new int[]{1, 3});
    assert Arrays.equals(solution.flipMatchVoyage(new int[]{1,2,3,4,5,6,7}, new int[]{1,2,3,4,5,6,7}), new int[]{-1});
    assert Arrays.equals(solution.flipMatchVoyage(new int[]{1,2,3,4,5,6,7}, new int[]{1,2,4,5,3,6,7}), new int[]{});
    assert Arrays.equals(solution.flipMatchVoyage(new int[]{1,2,3,4,5}, new int[]{1,3,5,4,2}), new int[]{-1});
    assert Arrays.equals(solution.flipMatchVoyage(new int[]{1,2,3}, new int[]{1,2,3}), new int[]{});
    assert Arrays.equals(solution.flipMatchVoyage(new int[]{1,2,3,4,5}, new int[]{1,2,4,5,3}), new int[]{});
    assert Arrays.equals(solution.flipMatchVoyage(new int[]{1,null,2}, new int[]{1,2}), new int[]{});
    assert Arrays.equals(solution.flipMatchVoyage(new int[]{1,2,3,4,5}, new int[]{1,3,2,5,4}), new int[]{1, 2});
    assert Arrays.equals(solution.flipMatchVoyage(new int[]{1,2,3,4,5,6,7}, new int[]{1,3,7,6,2,5,4}), new int[]{1, 3, 2});
    assert Arrays.equals(solution.flipMatchVoyage(new int[]{1,2,3,null,null,4,5}, new int[]{1,2,3,4,5}), new int[]{});
    assert Arrays.equals(solution.flipMatchVoyage(new int[]{1,2}, new int[]{2,1}), new int[]{-1});
    assert Arrays.equals(solution.flipMatchVoyage(new int[]{1,2,3,4,5,6,7}, new int[]{1,3,7,6,5,2,4}), new int[]{-1});
